frappe.ui.form.on('Payment Entry', {

    refresh(frm) {
        remove_8300_banner();                                  // always first — before any return
        if (frm.doc.party_type !== 'Customer') return;
        if (frm.doc.payment_type !== 'Receive') return;

        if (frm.is_new()) {
            maybe_show_8300_reminder(frm);
            return;
        }

        // Saved doc — fetch actual log status
        frappe.call({
            method: 'cannabis_management.cannabis_management.utils.irs_8300.get_8300_status_for_payment',
            args: { payment_entry_name: frm.doc.name },
            callback(r) {
                const log = r.message || null;

                frappe.call({
                    method: 'cannabis_management.cannabis_management.utils.irs_8300.get_8300_attachment_for_payment',
                    args: { payment_entry_name: frm.doc.name },
                    callback(a) {
                        const attachment = a.message || null;

                        if (log) {
                            render_8300_banner(frm, log, attachment);
                        } else {
                            check_if_cash_payment(frm, function(is_cash) {
                                if (is_cash && frm.doc.paid_amount > 10000) {
                                    render_8300_no_log_banner(frm);
                                }
                            });
                        }
                    }
                });
            }
        });
    },

    payment_type(frm) {
        remove_8300_banner();
        if (frm.doc.party_type === 'Customer' && frm.doc.payment_type === 'Receive') {
            maybe_show_8300_reminder(frm);
        }
    },

    party_type(frm) {
        remove_8300_banner();
        if (frm.doc.party_type === 'Customer' && frm.doc.payment_type === 'Receive') {
            maybe_show_8300_reminder(frm);
        }
    },

    mode_of_payment(frm) {
        if (frm.doc.party_type === 'Customer' && frm.doc.payment_type === 'Receive') {
            maybe_show_8300_reminder(frm);
        }
    },

    paid_amount(frm) {
        if (frm.doc.party_type === 'Customer' && frm.doc.payment_type === 'Receive') {
            maybe_show_8300_reminder(frm);
        }
    }

});


// ── Helpers ───────────────────────────────────────────────────────────────────

function remove_8300_banner() {
    $('.irs-8300-section').remove();
}

function inject_banner(html) {
    remove_8300_banner();
    $('.layout-main-section').first().prepend(html);
}

function check_if_cash_payment(frm, callback) {
    if (!frm.doc.mode_of_payment) return callback(false);
    frappe.db.get_value('Mode of Payment', frm.doc.mode_of_payment, 'type', function(r) {
        callback(r && r.type === 'Cash');
    });
}


// ── New / unsaved doc reminder ────────────────────────────────────────────────

function maybe_show_8300_reminder(frm) {
    remove_8300_banner();
    if (!frm.doc.mode_of_payment || !(frm.doc.paid_amount > 10000)) return;

    check_if_cash_payment(frm, function(is_cash) {
        if (!is_cash) return;

        inject_banner(`
            <div class="irs-8300-section" style="
                background:#fff8e1;
                border-left:4px solid #ffc107;
                border-radius:6px;
                padding:12px 16px;
                margin:12px 0 4px;
                display:flex;
                align-items:flex-start;
                gap:10px;
            ">
                <span style="font-size:20px;line-height:1;">⚠️</span>
                <div>
                    <strong style="font-size:13px;color:#7c4700;">IRS Form 8300 Required</strong><br>
                    <span style="font-size:12px;color:#5a3e00;">
                        Cash payments over $10,000 require Form 8300 filing within 15 days of receipt.
                        A log will be created automatically when this payment is submitted.
                    </span>
                </div>
            </div>
        `);
    });
}


// ── Saved doc — log exists ────────────────────────────────────────────────────

function render_8300_banner(frm, log, attachment) {
    const statusColors = {
        'Pending':        { bg: '#fff8e1', border: '#ffc107', text: '#7c4700', icon: '⏳' },
        'Overdue':        { bg: '#ffebee', border: '#e53935', text: '#7f0000', icon: '🚨' },
        'Filed - E-File': { bg: '#e8f5e9', border: '#43a047', text: '#1b5e20', icon: '✅' },
        'Filed - Paper':  { bg: '#e8f5e9', border: '#43a047', text: '#1b5e20', icon: '✅' },
        'Reported':       { bg: '#e3f2fd', border: '#1e88e5', text: '#0d47a1', icon: '📋' },
    };

    const c = statusColors[log.filing_status] || statusColors['Pending'];

    // Deadline text
    const days_left = log.days_left;
    let deadline_text = '';
    if (days_left > 0) {
        deadline_text = `<span style="color:#e65100;font-weight:600;">${days_left} days left to file</span>`;
    } else if (days_left === 0) {
        deadline_text = `<span style="color:#e53935;font-weight:700;">Due TODAY</span>`;
    } else {
        deadline_text = `<span style="color:#c62828;font-weight:700;">OVERDUE by ${Math.abs(days_left)} days</span>`;
    }

    // FinCEN confirmation
    const conf = log.fincen_confirmation_number
        ? `<span style="margin-left:12px;color:#1b5e20;">
               FinCEN Conf #: <strong>${log.fincen_confirmation_number}</strong>
           </span>`
        : '';

    // Suspicious activity warning — never send Jan 31 notice for these
    const suspicious_warn = log.is_suspicious_activity
        ? `<div style="
               margin-top:6px;font-size:11px;
               color:#7f0000;font-weight:600;
               background:#fff3e0;padding:4px 8px;border-radius:4px;display:inline-block;
           ">
               ⚠️ Suspicious activity filing — January 31 notice will NOT be sent to this customer (IRS rule)
           </div>`
        : '';

    // Related transaction flag
    const related_flag = log.is_related_transaction
        ? `<span style="
               margin-left:8px;font-size:10px;font-weight:600;
               background:#e3f2fd;color:#1565c0;
               padding:2px 6px;border-radius:3px;
           ">Related Transactions</span>`
        : '';

    // Attach / view button
    const attach_btn = !attachment
        ? `<button class="btn btn-xs btn-default"
               onclick="attach_8300_form('${log.name}', '${frm.doc.name}')">
               📎 Attach Form 8300
           </button>`
        : `<a href="${attachment.file_url}" target="_blank" class="btn btn-xs btn-default">
               📄 View Attached Form
           </a>`;

    // Mark as filed button — only for Pending / Overdue
    const file_btn = ['Pending', 'Overdue'].includes(log.filing_status)
        ? `<button class="btn btn-xs btn-warning" style="margin-left:6px;"
               onclick="mark_as_filed_prompt('${log.name}', '${frm.doc.name}')">
               Mark as Filed
           </button>`
        : '';

    inject_banner(`
        <div class="irs-8300-section" style="
            background:${c.bg};
            border-left:4px solid ${c.border};
            border-radius:6px;
            padding:12px 16px;
            margin:12px 0 4px;
        ">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px;">
                <div>
                    <strong style="font-size:13px;color:${c.text};">
                        ${c.icon} IRS Form 8300 — ${log.filing_status}
                        ${related_flag}
                    </strong><br>
                    <span style="font-size:12px;color:${c.text};">
                        Log: <a href="/app/irs-form-8300-log/${log.name}" target="_blank"
                               style="color:${c.text};text-decoration:underline;">${log.name}</a>
                        &nbsp;·&nbsp;
                        Cash Amount: <strong>$${parseFloat(log.cash_amount).toLocaleString('en-US', {minimumFractionDigits:2})}</strong>
                        &nbsp;·&nbsp;
                        Deadline: <strong>${log.filing_deadline}</strong>
                        &nbsp;·&nbsp;
                        ${deadline_text}
                        ${conf}
                    </span>
                    ${suspicious_warn}
                </div>
                <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                    ${attach_btn}
                    ${file_btn}
                </div>
            </div>
        </div>
    `);
}


// ── Saved doc — qualifies but no log yet ──────────────────────────────────────

function render_8300_no_log_banner(frm) {
    inject_banner(`
        <div class="irs-8300-section" style="
            background:#ffebee;
            border-left:4px solid #e53935;
            border-radius:6px;
            padding:12px 16px;
            margin:12px 0 4px;
            display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;
        ">
            <div>
                <strong style="font-size:13px;color:#7f0000;">🚨 Form 8300 Log Missing</strong><br>
                <span style="font-size:12px;color:#7f0000;">
                    This cash payment exceeds $10,000 but no IRS Form 8300 log was found.
                </span>
            </div>
            <button class="btn btn-xs btn-danger"
                onclick="manually_create_8300_log('${frm.doc.name}')">
                Create Log Now
            </button>
        </div>
    `);
}


// ── Action functions ──────────────────────────────────────────────────────────

function manually_create_8300_log(payment_entry_name) {
    frappe.confirm(
        'Create IRS Form 8300 log for this payment?',
        function() {
            frappe.call({
                method: 'cannabis_management.cannabis_management.utils.irs_8300.scan_payment_for_8300',
                args: { payment_entry_name },
                freeze: true,
                freeze_message: 'Creating 8300 log...',
                callback(r) {
                    if (r.message && r.message.log && r.message.log.name) {
                        frappe.show_alert({
                            message:   'Log created: ' + r.message.log.name,
                            indicator: 'orange'
                        });
                        cur_frm.reload_doc();
                    } else {
                        frappe.msgprint(
                            r.message && r.message.log
                                ? r.message.log
                                : 'Could not create log — check payment mode and amount.'
                        );
                    }
                }
            });
        }
    );
}


function mark_as_filed_prompt(log_name, payment_entry_name) {
    const d = new frappe.ui.Dialog({
        title: 'Mark IRS Form 8300 as Filed',
        fields: [
            {
                label:     'Filing Method',
                fieldname: 'status',
                fieldtype: 'Select',
                options:   'Filed - E-File\nFiled - Paper',
                reqd:      1
            },
            {
                label:     'Filing Date',
                fieldname: 'filing_date',
                fieldtype: 'Date',
                default:   frappe.datetime.get_today(),
                reqd:      1
            },
            {
                label:     'FinCEN Confirmation Number (E-File only)',
                fieldname: 'conf_number',
                fieldtype: 'Data'
            }
        ],
        primary_action_label: 'Mark as Filed',
        primary_action(values) {
            frappe.call({
                method: 'cannabis_management.cannabis_management.utils.irs_8300.mark_8300_as_filed',
                args: {
                    log_name,
                    status:      values.status,
                    filing_date: values.filing_date,
                    conf_number: values.conf_number || null
                },
                freeze: true,
                callback(r) {
                    if (r.message && r.message.success) {
                        frappe.show_alert({
                            message:   'Form 8300 marked as filed',
                            indicator: 'green'
                        });
                        d.hide();
                        cur_frm.reload_doc();
                    }
                }
            });
        }
    });
    d.show();
}


function attach_8300_form(log_name, payment_entry_name) {
    new frappe.ui.FileUploader({
        doctype:  'Payment Entry',
        docname:  payment_entry_name,
        frm:      cur_frm,
        on_success(file) {
            frappe.call({
                method: 'cannabis_management.cannabis_management.utils.irs_8300.mark_8300_as_filed',
                args: {
                    log_name,
                    status:   'Filed - Paper',
                    file_url: file.file_url
                },
                callback() {
                    frappe.show_alert({
                        message:   'Form 8300 attached and logged',
                        indicator: 'green'
                    });
                    cur_frm.reload_doc();
                }
            });
        }
    });
}

frappe.ui.form.on("Purchase Invoice", {
    refresh(frm) {
        frm.add_custom_button("Get Shipments", async function () {

            if (!frm.doc.supplier) {
                frappe.msgprint("Please select Supplier first.");
                return;
            }

            // 🔥 0️⃣ FIRST: Get item code from Shipment Settings
            let settings = await frappe.db.get_doc("Shipment Settings");

            if (!settings || !settings.item) {
                frappe.msgprint("Please set the Shipment Item in Shipment Settings.");
                return;
            }

            let shipment_item_code = settings.item;

            frappe.call({
                method: "cannabis_management.cannabis_management.custom.purchase_invoice.get_shipments_for_invoice",
                args: { supplier: frm.doc.supplier },
                callback: async function (r) {

                    if (!r.message || r.message.length === 0) {
                        frappe.msgprint("No Shipment Found for this supplier.");
                        return;
                    }

                    // 1️⃣ Remove default blank row
                    if (frm.doc.items && frm.doc.items.length === 1) {
                        let row = frm.doc.items[0];
                        if (!row.item_code) {
                            frm.clear_table("items");
                        }
                    }

                    // 2️⃣ Fetch Item master details from settings item
                    let item = await frappe.db.get_value(
                        "Item",
                        shipment_item_code,
                        ["item_code", "item_name", "stock_uom"]
                    );

                    if (!item || !item.message || !item.message.item_code) {
                        frappe.msgprint("Shipment Item defined in Shipment Settings is invalid.");
                        return;
                    }

                    // 3️⃣ Check already added shipments → prevent duplicates
                    let existing_shipments = frm.doc.items.map(i => i.description);

                    r.message.forEach(sh => {

                        let desc = "Shipment: " + sh.name;

                        if (existing_shipments.includes(desc)) {
                            return;
                        }

                        let row = frm.add_child("items");
                        row.item_code = item.message.item_code;
                        row.item_name = item.message.item_name;
                        row.uom = item.message.stock_uom;
                        row.qty = 1;
                        row.rate = sh.shipment_amount || 0;
                        row.description = desc;
                    });

                    frm.refresh_field("items");
                }
            });
        });
    }
});


