frappe.ui.form.on('Shipment', {
    before_submit: function(frm) {
        // Prevent default submission
        frappe.validated = false;

        if (!frm.doc.pickup_date) {
            frappe.msgprint(__('Pickup Date not set!'));
            return;
        }

        let draft_dns = [];

        // Check all DNs status
        frm.doc.shipment_delivery_note.forEach(function(row) {
            if (row.delivery_note) {
                draft_dns.push(row.delivery_note);
            }
        });

        if (draft_dns.length === 0) {
            // No DNs to process, allow submission
            frappe.validated = true;
            return;
        }

        // Process all draft DNs
        let completed = 0;
        let total = draft_dns.length;
        let has_error = false;

        draft_dns.forEach(function(dn_name) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Delivery Note",
                    name: dn_name
                },
                async: false,  // ✅ Synchronous to prevent shipment submission
                callback: function(r) {
                    if (!r.message) {
                        has_error = true;
                        frappe.msgprint(__('Could not fetch Delivery Note {0}', [dn_name]));
                        return;
                    }

                    let dn = r.message;

                    // ✅ If already submitted, skip
                    if (dn.docstatus === 1) {
                        completed++;
                        return;
                    }

                    // ✅ If draft, update and submit
                    if (dn.docstatus === 0) {
                        frappe.call({
                            method: "frappe.client.set_value",
                            args: {
                                doctype: "Delivery Note",
                                name: dn.name,
                                fieldname: {
                                    posting_date: frm.doc.pickup_date,
                                    custom_shipment: frm.doc.name
                                }
                            },
                            async: false,
                            callback: function(res) {
                                if (!res || res.exc) {
                                    has_error = true;
                                    frappe.msgprint(__('Failed to update Delivery Note {0}', [dn.name]));
                                    return;
                                }

                                // Fetch fresh doc and submit
                                frappe.call({
                                    method: "frappe.client.get",
                                    args: {
                                        doctype: "Delivery Note",
                                        name: dn.name
                                    },
                                    async: false,
                                    callback: function(fresh_r) {
                                        if (!fresh_r.message) {
                                            has_error = true;
                                            frappe.msgprint(__('Could not fetch updated Delivery Note {0}', [dn.name]));
                                            return;
                                        }

                                        frappe.call({
                                            method: "frappe.client.submit",
                                            args: {
                                                doc: fresh_r.message
                                            },
                                            async: false,
                                            callback: function(s) {
                                                if (!s || s.exc) {
                                                    has_error = true;
                                                    frappe.msgprint(__('Failed to submit Delivery Note {0}', [dn.name]));
                                                } else {
                                                    completed++;
                                                    frappe.show_alert({
                                                        message: __('Delivery Note {0} submitted', [dn.name]),
                                                        indicator: 'green'
                                                    });
                                                }
                                            }
                                        });
                                    }
                                });
                            }
                        });
                    }
                }
            });
        });

        // ✅ Final validation
        if (has_error) {
            frappe.validated = false;
            frappe.msgprint({
                title: __('Submission Failed'),
                message: __('Cannot submit Shipment because some Delivery Notes failed to submit'),
                indicator: 'red'
            });
        } else if (completed === total) {
            frappe.validated = true;
            // Reload form to show updated status
            setTimeout(function() {
                frm.reload_doc();
            }, 1000);
        } else {
            frappe.validated = false;
        }
    }
});

frappe.ui.form.on('Sales Invoice', {
    onload(frm) {
        if (frm.is_new() && frm.doc.items && frm.doc.items.length > 0) {
            let sales_order = frm.doc.items[0].sales_order;
            if (sales_order) {
                frappe.db.get_value('Sales Order', sales_order, 'custom_pickup_or_dropoff', (r) => {
                    if (r && r.custom_pickup_or_dropoff) {
                        frm.set_value('custom_pickup_or_dropoff', r.custom_pickup_or_dropoff);
                    }
                });
            }
        }
    }
});

frappe.ui.form.on('Target Detail', {
    target_qty: function(frm, cdt, cdn) {
        calculate_target_amount(frm, cdt, cdn);
    },
    average_rate: function(frm, cdt, cdn) {
        calculate_target_amount(frm, cdt, cdn);
    }
});

function calculate_target_amount(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    if (row.target_qty && row.average_rate) {
        frappe.model.set_value(cdt, cdn, 'target_amount', row.target_qty * row.average_rate);
    }
}
